import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ConcurrentSkipListMap;

public class ConcurrentCollectionsDemo {
    public static void main(String[] args) {
        ConcurrentMap<String, Integer> scoreMap = new ConcurrentSkipListMap<>();
        scoreMap.put("Alice", 95);
        scoreMap.put("Bob", 82);
        scoreMap.putIfAbsent("Charlie", 88);

        System.out.println("Sorted Map First Entry: " + scoreMap.firstEntry());

        ConcurrentLinkedQueue<String> taskQueue = new ConcurrentLinkedQueue<>();
        taskQueue.offer("Task-1");
        taskQueue.offer("Task-2");

        String nextTask;
        while ((nextTask = taskQueue.poll()) != null) {
            System.out.println("Processing: " + nextTask);
        }
    }
}
